/// <summary>
/// CB355_DutyRoll(ExciseRegister)
/// Batch task service class for Duty roll monthly.
/// </summary>
class METDutyRollMonthlyTaskService extends METSysOperationTaskService
{
    METDutyRollMonthlyQueue     dutyRollMonthlyQueue;
    guid                        topPickingProcessId;
    boolean                     adHoc;
    boolean                     runForExcise;
    boolean                     immediateChange;
    utcdatetime                 startDate;
    METDutyRollMonthlyContract  contract;

}

Method.Source:
/// <summary>
///  Initializes the object.
/// </summary>
protected void initialise()
{                
    super();

    // get the topPickingProcessId from the contract
    contract            = dataContract as METDutyRollMonthlyContract;
    topPickingProcessId = contract.parmTopPickingProcessId();
    adHoc               = contract.parmAdHoc();
    runForExcise        = contract.parmRunForExcise();
    immediateChange     = contract.parmImmediateChange();

    if (!adHoc)
    {
        startDate    = this.getFstMonday();
    }
    else if (adHoc && immediateChange)
    {
        startDate    = DateTimeUtil::newDateTime(DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone()), timeNow());
    }
    else
    {
        startDate    = this.getNextMonday();
    }
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METDutyRollMonthlyContract</c>.
/// </param>
public void process(METDutyRollMonthlyContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Runs tasks of the task service class.
/// </summary>
/// <param name = "_readPast">Table read past setting</param>
protected void processTask(boolean _readPast)
{
    while (this.getDataFromTopPickingQueue(topPickingProcessId, _readPast))
    {
        try
        {
            if (dutyRollMonthlyQueue.RecId != 0)
            {
                this.execute();
            }
        }
        catch (Exception::Error)
        {
            // Catch any exception so that any one error won't bring down
            // the entire process of sales order substitution.
            Global::exceptionTextFallThrough();
        }
    }
}

/// <summary>
/// Gets data from queue table <c>MetDutyRollMonthlyQueue</c>.
///</summary>
/// <param name = "_processId">Guid created and added in the contract <c>METDutyRollMonthlyContract</c>.</param>
/// <param name = "_readPast">boolean to read past records or not</param>
/// <returns>True, if data is retrieved from the queue; otherwise; false.</returns>
private boolean getDataFromTopPickingQueue(guid _processId, boolean _readPast)
{
    #OCCRetryCount

    METDutyRollMonthlyQueue     topPickingQueue;
    int                         backOffWait;

    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    topPickingQueue.readPast(_readPast);

    try
    {
        ttsbegin;

        select firstonly pessimisticlock topPickingQueue
            where topPickingQueue.ProcessId == _processId;

        if (topPickingQueue.RecId)
        {
            //Copies data in dutyRollMonthlyQueue from topPickingQueue buffer.
            topPickingQueue.data(dutyRollMonthlyQueue);

            topPickingQueue.delete();
        }
        else
        {
            ///Empties the table buffer of dutyRollMonthlyQueue.
            DictTable dutyRollMonthlyQueueDictTable = new DictTable(tableNum(METDutyRollMonthlyQueue));
            dutyRollMonthlyQueue = dutyRollMonthlyQueueDictTable.makeRecord();
        }

        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return (dutyRollMonthlyQueue.RecId != 0);
}

/// <summary>
/// Executes the process.
/// </summary>
private void execute()
{        
    ttsbegin;

    this.processSite();

    //NS - Created for the CB799 - to provide the extract of duty per case value after the batch job is finished.
    if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METDutyRollMonthlyBusinessEvents)))
    {
        METDutyRollMonthlyBusinessEvents::newFromDutyRollMonthly(contract).send();
    }
    else
    {
        error("@MET:DutyRollExtBusinessEventNotEnabled");
    }
    ttscommit;
    //NS - Created for the CB799 - to provide the extract of duty per case value after the batch job is finished.

    //Call Generate Ad Valorum Claim Batch
    if (adHoc)
    {
        this.processGenerateAdValorumClaimBatch(contract.parmSiteList(), contract.parmItemList());
    }

}

/// <summary>
/// Call Generate Ad Valorum Claim Batch
/// </summary>
/// <param name = "_siteList">SiteList</param>
/// <param name = "_itemList">ItemList</param>
public void processGenerateAdValorumClaimBatch(List _siteList, List _itemList)
{
    try
    {
        ttsbegin;
        BatchHeader     batchHeaderCurrent;

        batchHeaderCurrent = this.getCurrentBatchHeader();

        SysOperationServiceController controller = new SysOperationServiceController(classStr(METDutyAdValorumClaimGenerateService), methodStr(METDutyAdValorumClaimGenerateService, processOperation), SysOperationExecutionMode::ScheduledBatch);
        controller.parmExecutionMode(SysOperationExecutionMode::ScheduledBatch);
        controller.parmShowDialog(false);
        controller.parmLoadFromSysLastValue(false);
        controller.parmDialogCaption("@MET:GenerateAdValorumClaim");

        // Set contract parameters
        METDutyAdValorumClaimGenerateContract dutyAdValorumClaimGenerateContract = new METDutyAdValorumClaimGenerateContract();
        dutyAdValorumClaimGenerateContract = controller.getDataContractObject();
        dutyAdValorumClaimGenerateContract.parmDutyValuesBySite(true);
        dutyAdValorumClaimGenerateContract.parmGenerateClaims(false);
        dutyAdValorumClaimGenerateContract.parmFilterItemSite(true);
        dutyAdValorumClaimGenerateContract.parmSiteList(_siteList);
        dutyAdValorumClaimGenerateContract.parmItemList(_itemList);

        //add the batch tasks to the batch header
        batchHeaderCurrent.addTask(controller);

        //save the batch
        batchHeaderCurrent.save();
        ttscommit;
    }
    catch
    {
        error ('Generate Ad valorum claim batch scheduled is failed.');
    }
}

/// <summary>
/// Processes one site for the duty roll monthly task
/// </summary>
private void processSite()
{
    METDutyRollValuesTable  dutyRollValuesTable;
    METDutyRollValuesTable  dutyRollValuesTableLoc;
    METDutyRollValuesLine   dutyRollValuesLineLoc;

    dutyRollValuesTable = METDutyRollValuesTable::findActive(dutyRollMonthlyQueue.SiteId);


    if (adHoc && dutyRollValuesTable.RecId)
    {
        /*METDutyRollValuesLine dutyRollValuesLine;

        update_recordset dutyRollValuesLine
            setting EndDate = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone())
                where dutyRollValuesLine.Site == dutyRollMonthlyQueue.SiteId
                    && dutyRollValuesLine.ItemId == dutyRollMonthlyQueue.ItemId
                    && dutyRollValuesLine.RefRecId == dutyRollValuesTable.RecId
                    && dutyRollValuesLine.EndDate == dateNull();*/

        this.processItem(dutyRollMonthlyQueue.SiteId, dutyRollMonthlyQueue.ItemId, dutyRollValuesTable.RecId);                                                  
    }
    else
    {
        if (dutyRollValuesTable.RecId)
        {
            dutyRollValuesTable.selectForUpdate(true);
            dutyRollValuesTable.Status  = METDutyRollStatus::Inactive;
            dutyRollValuesTable.update();

            /*update_recordset dutyRollValuesLineLoc
                setting EndDate = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone())
                    where dutyRollValuesLineLoc.Site == dutyRollMonthlyQueue.SiteId
                        && dutyRollValuesLineLoc.RefRecId == dutyRollValuesTable.RecId
                        && dutyRollValuesLineLoc.EndDate == dateNull();*/
        }

        dutyRollValuesTableLoc.clear();
        dutyRollValuesTableLoc.Site = dutyRollMonthlyQueue.SiteId;
        dutyRollValuesTableLoc.Status = METDutyRollStatus::Active;
        dutyRollValuesTableLoc.insert();

        this.processItem(dutyRollMonthlyQueue.SiteId, dutyRollMonthlyQueue.ItemId, dutyRollValuesTableLoc.RecId);
    }             
}

/// <summary>
///  Processes a single item for the duty roll monthly
/// </summary>
/// <param name = "_siteId">InventSiteId</param>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_refRecId">RefRecId</param>
private void processItem(InventSiteId  _siteId, ItemId  _itemId, RefRecId   _refRecId)
{
    METDutyRollValuesLine       dutyRollValuesLine;
    InventTable                 inventTable = InventTable::find(_itemId);
    METInventTable              metInventTable = METInventTable::find(_itemId);
    METTariffItemCode           tariffItemCode;
    METExciseSiteDutySetup      exciseSiteDutySetup;
    Qty                         lalqty;
    container                   con;

    dutyRollValuesLine.clear();
    dutyRollValuesLine.CalcDate     = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
    dutyRollValuesLine.ValidFrom    = startDate;
    dutyRollValuesLine.RefRecId     = _refRecId;
    dutyRollValuesLine.Site         = _siteId;
    dutyRollValuesLine.ItemId       = _itemId;
    dutyRollValuesLine.ItemName     = inventTable.NameAlias;
    dutyRollValuesLine.Unit         = inventTable.salesUnitId();
    dutyRollValuesLine.AverageVFD   = this.calcAvgDutyCase(_itemId, _siteId);
    tariffItemCode                  = METTariffItemCode::findRecId(metInventTable.METTariffItemCodeBaseRecid);
    //Duty amount = (pack size * Bottlesize * (AlcStrn/100) * Duty-LAL) + (VFD * (Adval Rate/100))
    dutyRollValuesLine.TotalDutyPerCase = metInventTable.ItemPack * metInventTable.BottleSize * (metInventTable.AlcoholContent/100) * tariffItemCode.DutyLAL + (dutyRollValuesLine.AverageVFD * tariffItemCode.AdValoremOrBeerSubsidyRate/100);

    if(runForExcise)
    {
        exciseSiteDutySetup = METExciseSiteDutySetup::find(_siteId, _itemId, true);
        if (exciseSiteDutySetup.RecId)
        {
            // LAL = Alcohol Content (%) x Bottle Size (L) x Quantity (each)
            lalqty = (metInventTable.AlcoholContent / 100) * metInventTable.BottleSize * metInventTable.ItemPack;
            exciseSiteDutySetup.ExcisePerCase   = tariffItemCode.DutyLAL * lalqty;
            exciseSiteDutySetup.ValidFrom       = startDate;
            exciseSiteDutySetup.update();
        }

    }
    dutyRollValuesLine.insert();
}

/// <summary>
/// calculate date for the first monday of the next month
/// </summary>
/// <returns>TransDate</returns>
private utcdatetime getFstMonday()
{
    TransDate   transDate;
    int         day;
    int         daysToAdd;

    transDate   = dateMthFwd(DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone()), 1);
    //1st day if the next month
    transDate   = mkDate(1, mthOfYr(transDate), Year(transDate));
    //day of the week on the 1st day on the next month
    day         = dayOfWk(transDate);
    //count days to the next Monday
    daysToAdd   = 8 - day;
    //1st Monday of the next month
    transDate   = transDate + daysToAdd;

    return DateTimeUtil::newDateTime(transDate, timeNow());
}

/// <summary>
/// calculate date for the next monday of the current date
/// </summary>
/// <returns>TransDate</returns>
private TransDate getNextMonday()
{
    TransDate   transDate;
    int         day;
    int         daysToAdd;
    const int   valEight = 8;

    transDate   = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());

    day         = dayOfWk(transDate);
    daysToAdd   = valEight - day;

    transDate   = transDate + daysToAdd;

    return DateTimeUtil::newDateTime(transDate, timeNow(), DateTimeUtil::getCompanyTimeZone());
}

/// <summary>
/// calculate average VFD and average inventory quantity
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_siteId">InventSiteId</param>
/// <returns>METValueForDuty</returns>
private METValueForDuty calcAvgDutyCase(ItemId   _itemId, InventSiteId   _siteId)
{
    METValueForDuty avgDuty;
    METExciseInformationTable   exciseInformationTable;
    METExciseRegisterEntry      exciseRegisterEntry;
    PurchLine                   purchLine;
    TransDateTime               startDateTime;
    TransDateTime               endDateTime;
    TransDate                   transDate;
    int                         countRecords;
    Amount                      dutyRateReceived = 0;

    transDate = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
    endDateTime = DateTimeUtil::addSeconds(DateTimeUtil::newDateTime(transDate+1, 0), - 1);
    transDate = mkDate(1, mthOfYr(transDate), year(transDate));
    startDateTime = DateTimeUtil::newDateTime(transDate, 0);

    while select firstonly10 DutyRateReceived from exciseRegisterEntry
        order by CreatedDateTime desc
        where  exciseRegisterEntry.ItemId == _itemId
            && exciseRegisterEntry.SiteId == _siteId
        exists join exciseInformationTable
        where exciseInformationTable.InventTransType == InventTransType::Purch
            && exciseInformationTable.ItemId == _itemId
            && exciseInformationTable.SiteId == _siteId
            && exciseInformationTable.ReferenceNumber == exciseRegisterEntry.OrderNumber
        exists join purchLine
        where purchLine.InventTransId == exciseInformationTable.InventTransId
            && purchLine.CreatedDateTime >= startDateTime
            && purchLine.CreatedDateTime <= endDateTime
    {
        if (countRecords == METConstants::TenValue)
        {
            break;
        }

        dutyRateReceived += exciseRegisterEntry.DutyRateReceived;
        countRecords++;
    }

    if (countRecords)
    {
        avgDuty = dutyRateReceived / (countRecords);
    }

    return avgDuty;
}
